(sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = 'uniform mat4 uToModel; varying vec3 vRest;\n' + sh.vertexShader.replace('#include <begin_vertex>', '#include <begin_vertex>\n vRest = (uToModel * vec4(position, 1.0)).xyz;');
    sh.fragmentShader = 'uniform vec3 uDark; uniform vec3 uLight; uniform vec4 uBand; uniform vec4 uLed; uniform vec4 uSplit; uniform vec3 uShirt; uniform vec3 uPants; uniform vec3 uPrintA[2]; uniform vec3 uPrintB[2]; varying vec3 vRest;\n' + sh.fragmentShader.replace('#include <map_fragment>', `#include <map_fragment>
      { vec3 c = diffuseColor.rgb; float mx = max(c.r, max(c.g, c.b)), mn = min(c.r, min(c.g, c.b)), sa = (mx - mn) / (mx + 1e-4), lum = dot(c, vec3(0.2126, 0.7152, 0.0722));
        float skin = max(step(1.12, vRest.y) * (1.0 - step(0.46, abs(vRest.x))), step(0.83, abs(vRest.x)));   // the head and the hands
        float grey = 1.0 - smoothstep(0.32, 0.55, sa) * smoothstep(0.03, 0.07, mx);                            // near-black counts as cloth whatever its tint
        float emblem = (1.0 - grey) * (1.0 - skin);
        vec3 ra = vec3(abs(vRest.x), vRest.yz);
        for (int i = 0; i < 2; i++) if (all(greaterThan(ra, uPrintA[i])) && all(lessThan(ra, uPrintB[i]))) emblem = max(emblem, 0.8);
        lum = mix(lum, uBand.w, emblem); grey = max(grey, emblem);
        vec3 t = (lum + uBand.z) * mix(uDark, uLight, smoothstep(uBand.x, uBand.y, lum));
        if (uSplit.w > 0.5) {
          float k = clamp(0.62 + lum * 2.6, 0.45, 1.45);
          vec3 cloth = mix(uPants, uShirt, smoothstep(uSplit.x - 0.012, uSplit.x + 0.012, vRest.y));
          float keep = max(1.0 - smoothstep(uSplit.y - 0.015, uSplit.y + 0.015, vRest.y), smoothstep(uSplit.z - 0.02, uSplit.z + 0.02, abs(vRest.x)));
          t = mix(cloth * k, c * 0.85, keep);
        }
        c = mix(c, t, grey);
        float led = uLed.w * step(0.2, diffuseColor.r) * (1.0 - smoothstep(0.03, 0.08, diffuseColor.g / (diffuseColor.r + 1e-4)));
        diffuseColor.rgb = mix(c, uLed.rgb, led); }`);
  }

